<?php use App\Core\Csrf; $title = 'Administrator | LearnSpace'; require __DIR__ . '/_header.php'; ?>
<div class="row" style="justify-content:space-between"><div><h1>School administration</h1><p class="muted">Set up learning spaces, people, subjects, and course ownership.</p></div><a class="button secondary" href="/admin/users">Manage profiles</a></div>
<div class="grid">
<section class="card"><h2>Create a room / class</h2><form method="post" action="/admin/classes"><?= Csrf::field() ?><input name="name" required placeholder="e.g. Grade 10 A"><input name="academic_year" required placeholder="e.g. 2026-2027"><textarea name="description" placeholder="Optional description"></textarea><button>Create class</button></form></section>
<section class="card"><h2>Create a subject</h2><form method="post" action="/admin/subjects"><?= Csrf::field() ?><input name="name" required placeholder="e.g. Physics"><input name="code" placeholder="e.g. PHY-101"><input name="coefficient" type="number" min="0" step=".01" value="1"><textarea name="description" placeholder="Optional description"></textarea><button>Create subject</button></form></section>
<section class="card"><h2>Enroll a student</h2><form method="post" action="/admin/enrollments"><?= Csrf::field() ?><select name="student_id" required><option value="">Student</option><?php foreach ($students as $student): ?><option value="<?= $student['id'] ?>"><?= h($student['first_name'] . ' ' . $student['last_name']) ?></option><?php endforeach; ?></select><select name="class_id" required><option value="">Class</option><?php foreach ($classes as $class): ?><option value="<?= $class['id'] ?>"><?= h($class['name'] . ' · ' . $class['academic_year']) ?></option><?php endforeach; ?></select><input name="academic_year" required placeholder="Academic year"><button>Enroll student</button></form></section>
<section class="card"><h2>Assign a course</h2><form method="post" action="/admin/courses"><?= Csrf::field() ?><input name="title" required placeholder="Course title"><textarea name="description" placeholder="What will students learn?"></textarea><select name="subject_id" required><option value="">Subject</option><?php foreach ($subjects as $subject): ?><option value="<?= $subject['id'] ?>"><?= h($subject['name']) ?></option><?php endforeach; ?></select><select name="teacher_id" required><option value="">Professor</option><?php foreach ($teachers as $teacher): ?><option value="<?= $teacher['id'] ?>"><?= h($teacher['first_name'] . ' ' . $teacher['last_name']) ?></option><?php endforeach; ?></select><select name="class_id" required><option value="">Class</option><?php foreach ($classes as $class): ?><option value="<?= $class['id'] ?>"><?= h($class['name']) ?></option><?php endforeach; ?></select><select name="status"><option value="DRAFT">Draft</option><option value="PUBLISHED">Published</option></select><button>Assign course</button></form></section>
<section class="card wide"><h2>Courses</h2><?php if (!$courses): ?><p class="muted">No courses assigned yet.</p><?php endif; ?><?php foreach ($courses as $course): ?><div class="item"><strong><?= h($course['title']) ?></strong> <span class="pill"><?= h($course['status']) ?></span><div class="muted"><?= h($course['subject_name']) ?> · <?= h($course['class_name']) ?> · <?= h($course['teacher_name']) ?></div></div><?php endforeach; ?></section>
</div>
